import { motion } from "framer-motion";
import { Award } from "lucide-react";
import somaliBooksLogo from "@assets/SOMALI_BOOKS.jpg";
import ethiopiaMinTechLogo from "@assets/ETHIOPIA_MINSTERY_OF_TECHNOLOGY.jpg";
import eardipWorldBankLogo from "@assets/EARDIP_WORLDBANK_PROJECT.jpg";
import stratosphereLogo from "@assets/Stratosphere_Aeronautics.png";
import KeynanLogo from "@assets/Keynan.png";

const clients = [
  { name: "Somali Books", logo: somaliBooksLogo },
  { name: "Ethiopia Ministry of Technology", logo: ethiopiaMinTechLogo },
  { name: "EARDIP – Ministry of ICT Somaliland", logo: eardipWorldBankLogo },
  { name: "Stratosphere Aeronautics", logo: stratosphereLogo },
  { name: "Keynan Watch And Optical", logo: KeynanLogo },
];

// Duplicate for seamless infinite scroll
const track = [...clients, ...clients, ...clients];

export default function TrustedBy() {
  return (
    <section
      id="trusted-by"
      className="relative py-24 overflow-hidden"
      style={{ background: "linear-gradient(180deg,#03080f 0%,#07111f 50%,#03080f 100%)" }}
    >
      {/* Background grid */}
      <div className="absolute inset-0 cyber-grid opacity-20" />

      {/* Gradient edge fades */}
      <div
        className="absolute inset-y-0 left-0 w-32 z-10 pointer-events-none"
        style={{ background: "linear-gradient(90deg,#03080f,transparent)" }}
      />
      <div
        className="absolute inset-y-0 right-0 w-32 z-10 pointer-events-none"
        style={{ background: "linear-gradient(270deg,#03080f,transparent)" }}
      />

      <div className="container mx-auto px-4 relative z-10">
        {/* Heading */}
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.7 }}
          className="text-center mb-16"
        >
          <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full glass mb-6 border border-yellow-400/20">
            <Award size={14} className="text-yellow-400" />
            <span className="text-xs text-yellow-400 tracking-widest uppercase font-semibold">
              Our Clients
            </span>
          </div>
          <h2 className="text-4xl lg:text-5xl font-black gradient-text mb-4">Trusted By</h2>
          <p className="text-slate-400 max-w-2xl mx-auto text-lg">
            Organizations that trust us to secure and empower their digital future.
          </p>
        </motion.div>
      </div>

      {/* Scrolling marquee track — full-width, outside container */}
      <div className="relative overflow-hidden">
        <div className="flex gap-12 w-max animate-marquee">
          {track.map((client, i) => (
            <div
              key={i}
              className="flex flex-col items-center gap-4 group flex-shrink-0"
            >
              {/* Logo circle */}
              <div
                className="w-36 h-36 rounded-full glass border border-white/8 flex items-center justify-center p-4 transition-all duration-500 group-hover:border-yellow-400/50"
                style={{ boxShadow: "0 0 0 0 rgba(251,191,36,0)" }}
                onMouseEnter={(e) => {
                  (e.currentTarget as HTMLDivElement).style.boxShadow =
                    "0 0 30px rgba(251,191,36,0.25), 0 0 60px rgba(251,191,36,0.1)";
                }}
                onMouseLeave={(e) => {
                  (e.currentTarget as HTMLDivElement).style.boxShadow =
                    "0 0 0 0 rgba(251,191,36,0)";
                }}
              >
                <img
                  src={client.logo}
                  alt={client.name}
                  className="w-full h-full object-contain rounded-full transition-transform duration-500 group-hover:scale-110"
                  style={{ filter: "drop-shadow(0 2px 8px rgba(0,0,0,0.5))" }}
                />
              </div>
              {/* Name */}
              <p className="text-center text-xs font-semibold text-slate-400 max-w-[130px] leading-snug group-hover:text-yellow-300 transition-colors duration-300">
                {client.name}
              </p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

"use client"

import * as React from "react"
import * as SheetPrimitive from "@radix-ui/react-dialog"
import { cva, type VariantProps } from "class-variance-authority"
import { X } from "lucide-react"

import { cn } from "@/lib/utils"

const Sheet = SheetPrimitive.Root

const SheetTrigger = SheetPrimitive.Trigger

const SheetClose = SheetPrimitive.Close

const SheetPortal = SheetPrimitive.Portal

const SheetOverlay = React.forwardRef<
  React.ElementRef<typeof SheetPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof SheetPrimitive.Overlay>
>(({ className, ...props }, ref) => (
  <SheetPrimitive.Overlay
    className={cn(
      "fixed inset-0 z-50 bg-black/80  data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0",
      className
    )}
    {...props}
    ref={ref}
  />
))
SheetOverlay.displayName = SheetPrimitive.Overlay.displayName

const sheetVariants = cva(
  "fixed z-50 gap-4 bg-background p-6 shadow-lg transition ease-in-out data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:duration-300 data-[state=open]:duration-500",
  {
    variants: {
      side: {
        top: "inset-x-0 top-0 border-b data-[state=closed]:slide-out-to-top data-[state=open]:slide-in-from-top",
        bottom:
          "inset-x-0 bottom-0 border-t data-[state=closed]:slide-out-to-bottom data-[state=open]:slide-in-from-bottom",
        left: "inset-y-0 left-0 h-full w-3/4 border-r data-[state=closed]:slide-out-to-left data-[state=open]:slide-in-from-left sm:max-w-sm",
        right:
          "inset-y-0 right-0 h-full w-3/4  border-l data-[state=closed]:slide-out-to-right data-[state=open]:slide-in-from-right sm:max-w-sm",
      },
    },
    defaultVariants: {
      side: "right",
    },
  }
)

interface SheetContentProps
  extends React.ComponentPropsWithoutRef<typeof SheetPrimitive.Content>,
    VariantProps<typeof sheetVariants> {}

const SheetContent = React.forwardRef<
  React.ElementRef<typeof SheetPrimitive.Content>,
  SheetContentProps
>(({ side = "right", className, children, ...props }, ref) => (
  <SheetPortal>
    <SheetOverlay />
    <SheetPrimitive.Content
      ref={ref}
      className={cn(sheetVariants({ side }), className)}
      {...props}
    >
      {children}
      <SheetPrimitive.Close className="absolute right-4 top-4 rounded-sm opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:pointer-events-none data-[state=open]:bg-secondary">
        <X className="h-4 w-4" />
        <span className="sr-only">Close</span>
      </SheetPrimitive.Close>
    </SheetPrimitive.Content>
  </SheetPortal>
))
SheetContent.displayName = SheetPrimitive.Content.displayName

const SheetHeader = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    className={cn(
      "flex flex-col space-y-2 text-center sm:text-left",
      className
    )}
    {...props}
  />
)
SheetHeader.displayName = "SheetHeader"

const SheetFooter = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    className={cn(
      "flex flex-col-reverse sm:flex-row sm:justify-end sm:space-x-2",
      className
    )}
    {...props}
  />
)
SheetFooter.displayName = "SheetFooter"

const SheetTitle = React.forwardRef<
  React.ElementRef<typeof SheetPrimitive.Title>,
  React.ComponentPropsWithoutRef<typeof SheetPrimitive.Title>
>(({ className, ...props }, ref) => (
  <SheetPrimitive.Title
    ref={ref}
    className={cn("text-lg font-semibold text-foreground", className)}
    {...props}
  />
))
SheetTitle.displayName = SheetPrimitive.Title.displayName

const SheetDescription = React.forwardRef<
  React.ElementRef<typeof SheetPrimitive.Description>,
  React.ComponentPropsWithoutRef<typeof SheetPrimitive.Description>
>(({ className, ...props }, ref) => (
  <SheetPrimitive.Description
    ref={ref}
    className={cn("text-sm text-muted-foreground", className)}
    {...props}
  />
))
SheetDescription.displayName = SheetPrimitive.Description.displayName

export {
  Sheet,
  SheetPortal,
  SheetOverlay,
  SheetTrigger,
  SheetClose,
  SheetContent,
  SheetHeader,
  SheetFooter,
  SheetTitle,
  SheetDescription,
}

