@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@400;500;700;900&family=Inter:wght@300;400;500;600;700&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --background: 220 60% 4%;
  --foreground: 0 0% 98%;
  --muted: 220 40% 10%;
  --muted-foreground: 210 15% 65%;
  --popover: 220 60% 4%;
  --popover-foreground: 0 0% 98%;
  --card: 220 40% 8%;
  --card-foreground: 0 0% 98%;
  --border: 45 100% 55% / 0.15;
  --input: 220 40% 10%;
  --primary: 45 100% 55%;
  --primary-foreground: 220 60% 4%;
  --secondary: 220 40% 10%;
  --secondary-foreground: 0 0% 98%;
  --accent: 220 40% 10%;
  --accent-foreground: 0 0% 98%;
  --destructive: 0 84.2% 60.2%;
  --destructive-foreground: 60 9.1% 97.8%;
  --ring: 45 100% 55%;
  --radius: 0.75rem;

  --cyber-blue: #03080f;
  --cyber-blue-mid: #060d1a;
  --cyber-yellow: #fbbf24;
  --cyber-yellow-glow: rgba(251, 191, 36, 0.4);
  --cyber-cyan: #22d3ee;
  --cyber-cyan-glow: rgba(34, 211, 238, 0.3);
}

* { box-sizing: border-box; }

html {
  scroll-behavior: smooth;
  background: var(--cyber-blue);
}

body {
  @apply antialiased;
  background: var(--cyber-blue);
  color: #e8f0fe;
  font-family: 'Inter', sans-serif;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  font-family: 'Orbitron', monospace;
  letter-spacing: 0.05em;
}

::-webkit-scrollbar { width: 6px; }
::-webkit-scrollbar-track { background: #03080f; }
::-webkit-scrollbar-thumb { background: #fbbf24; border-radius: 3px; }

/* ── Glow ─────────────────────────────────────────────────── */
.glow-yellow {
  box-shadow:
    0 0 15px rgba(251,191,36,0.4),
    0 0 40px rgba(251,191,36,0.15),
    inset 0 0 15px rgba(251,191,36,0.05);
}
.glow-cyan {
  box-shadow: 0 0 20px rgba(34,211,238,0.35), 0 0 50px rgba(34,211,238,0.1);
}
.text-glow-yellow {
  text-shadow: 0 0 20px rgba(251,191,36,0.9), 0 0 50px rgba(251,191,36,0.5);
}
.text-glow-cyan {
  text-shadow: 0 0 20px rgba(34,211,238,0.9), 0 0 50px rgba(34,211,238,0.5);
}

/* ── Glass ────────────────────────────────────────────────── */
.glass {
  background: rgba(255,255,255,0.03);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(251,191,36,0.12);
}
.glass-dark {
  background: rgba(3,8,15,0.75);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  border: 1px solid rgba(251,191,36,0.1);
}

/* ── 3D Card Flip ─────────────────────────────────────────── */
.card-3d-container {
  perspective: 1000px;
  cursor: pointer;
}
.card-3d-inner {
  position: relative;
  width: 100%;
  height: 100%;
  transition: transform 0.7s cubic-bezier(0.4, 0.2, 0.2, 1);
  transform-style: preserve-3d;
}
.card-3d-container:hover .card-3d-inner {
  transform: rotateY(180deg);
}
.card-3d-front,
.card-3d-back {
  position: absolute;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  border-radius: 1rem;
}
.card-3d-back {
  transform: rotateY(180deg);
}

/* ── Gradient text ────────────────────────────────────────── */
.gradient-text {
  background: linear-gradient(135deg, #fbbf24 0%, #f59e0b 40%, #22d3ee 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.gradient-text-cyan {
  background: linear-gradient(135deg, #22d3ee, #818cf8);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ── Cyber grid ───────────────────────────────────────────── */
.cyber-grid {
  background-image:
    linear-gradient(rgba(251,191,36,0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(251,191,36,0.04) 1px, transparent 1px);
  background-size: 60px 60px;
  animation: grid-move 10s linear infinite;
}

/* ── Animations ───────────────────────────────────────────── */
@keyframes float {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-20px); }
}
@keyframes float-slow {
  0%, 100% { transform: translateY(0px) rotate(0deg); }
  50% { transform: translateY(-28px) rotate(4deg); }
}
@keyframes grid-move {
  0% { background-position: 0 0; }
  100% { background-position: 60px 60px; }
}
@keyframes pulse-glow {
  0%, 100% { box-shadow: 0 0 20px rgba(251,191,36,0.3); }
  50% { box-shadow: 0 0 60px rgba(251,191,36,0.6), 0 0 100px rgba(251,191,36,0.2); }
}
@keyframes rotate-3d {
  0%   { transform: rotateX(0deg)  rotateY(0deg);   }
  25%  { transform: rotateX(10deg) rotateY(90deg);  }
  50%  { transform: rotateX(0deg)  rotateY(180deg); }
  75%  { transform: rotateX(-10deg) rotateY(270deg);}
  100% { transform: rotateX(0deg)  rotateY(360deg); }
}
@keyframes slide-up {
  from { transform: translateY(60px); opacity: 0; }
  to   { transform: translateY(0);    opacity: 1; }
}
@keyframes neon-border {
  0%, 100% { border-color: rgba(251,191,36,0.3); }
  50%       { border-color: rgba(251,191,36,0.8); }
}
@keyframes scan {
  0%   { top: -10%; }
  100% { top: 110%; }
}

.animate-float      { animation: float 6s ease-in-out infinite; }
.animate-float-slow { animation: float-slow 9s ease-in-out infinite; }
.animate-pulse-glow { animation: pulse-glow 3s ease-in-out infinite; }
.animate-rotate-3d  { animation: rotate-3d 14s linear infinite; }
.animate-slide-up   { animation: slide-up 0.8s ease forwards; }
.animate-marquee    { animation: marquee 28s linear infinite; }
.animate-marquee:hover { animation-play-state: paused; }

@keyframes marquee {
  0%   { transform: translateX(0); }
  100% { transform: translateX(-33.333%); }
}

/* ── 3D Button ────────────────────────────────────────────── */
.btn-3d {
  position: relative;
  transform-style: preserve-3d;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.btn-3d:hover  { transform: translateY(-4px); }
.btn-3d:active { transform: translateY(2px); }

/* ── Section divider ──────────────────────────────────────── */
.section-divider {
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(251,191,36,0.5), rgba(34,211,238,0.5), transparent);
}

/* ── Scanlines overlay ────────────────────────────────────── */
.scanlines {
  position: relative;
}
.scanlines::before {
  content: '';
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 3px,
    rgba(0,0,0,0.06) 3px,
    rgba(0,0,0,0.06) 4px
  );
  pointer-events: none;
  z-index: 2;
}

